-- =============================================================================
-- STATIC DATA: Natural Earth Physical Centerlines
-- Schema:  aux_data
-- Source:  Natural Earth ne_10m_rivers_lake_centerlines (static, bundled)
-- Notes:   460 features. scalerank/min_label/max_label carry NE cartographic
--          priority signals for river/drainage label visibility. Loaded once —
--          this dataset does not change between pipeline runs.
-- =============================================================================

BEGIN;
DROP TABLE IF EXISTS aux_data.ne_physical_centerlines CASCADE;
CREATE TABLE aux_data.ne_physical_centerlines (
    id          SERIAL PRIMARY KEY,
    geometry    geometry(LINESTRING, 4326),
    featurecla  VARCHAR,
    name        VARCHAR,
    namealt     VARCHAR,
    region      VARCHAR,
    subregion   VARCHAR,
    min_label   FLOAT8,
    max_label   FLOAT8,
    scalerank   INTEGER,
    label       VARCHAR,
    wikidataid  VARCHAR,
    name_ar     VARCHAR,
    name_bn     VARCHAR,
    name_de     VARCHAR,
    name_en     VARCHAR,
    name_es     VARCHAR,
    name_fr     VARCHAR,
    name_el     VARCHAR,
    name_hi     VARCHAR,
    name_hu     VARCHAR,
    name_id     VARCHAR,
    name_it     VARCHAR,
    name_ja     VARCHAR,
    name_ko     VARCHAR,
    name_nl     VARCHAR,
    name_pl     VARCHAR,
    name_pt     VARCHAR,
    name_ru     VARCHAR,
    name_sv     VARCHAR,
    name_tr     VARCHAR,
    name_vi     VARCHAR,
    name_zh     VARCHAR,
    ne_id       INTEGER,
    name_fa     VARCHAR,
    name_he     VARCHAR,
    name_uk     VARCHAR,
    name_ur     VARCHAR,
    name_zht    VARCHAR
);


CREATE INDEX idx_ne_physical_centerlines_geometry  ON aux_data.ne_physical_centerlines USING gist(geometry);
CREATE INDEX idx_ne_physical_centerlines_scalerank ON aux_data.ne_physical_centerlines USING btree(scalerank);
CREATE INDEX idx_ne_physical_centerlines_name      ON aux_data.ne_physical_centerlines USING btree(name) WHERE name IS NOT NULL;
COMMIT;
